create policy "customer_success_reviews_service_all" on public.customer_success_reviews for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');
create policy "client_health_rollups_service_all" on public.client_health_rollups for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');
create policy "client_operating_playbook_templates_service_all" on public.client_operating_playbook_templates for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');
